package example
import "context"
// nil channel 禁用读分支，取消仍可唤醒 select。
func SumChannel(ctx context.Context,input <-chan int)(int,error){
    sum:=0
    for {if err:=ctx.Err();err!=nil{return sum,err}
        select {case <-ctx.Done():return sum,ctx.Err()
        case v,ok:=<-input:if !ok{return sum,nil};sum+=v}
    }
}

// fixture version 2

package example
import ("context"; "errors"; "testing"; "time")
func TestServerChannelSumAndClose(t *testing.T) {
    ch:=make(chan int,4);for _,v:=range []int{3,-1,0,8}{ch<-v};close(ch)
    sum,err:=SumChannel(context.Background(),ch)
    if err!=nil||sum!=10{t.Fatalf("求和错误: %v %v",sum,err)}
    empty:=make(chan int);close(empty)
    sum,err=SumChannel(context.Background(),empty)
    if err!=nil||sum!=0{t.Fatal("空 channel 错误")}
}
func TestServerNilChannelCancellation(t *testing.T) {
    ctx,cancel:=context.WithTimeout(context.Background(),30*time.Millisecond);defer cancel()
    if _,err:=SumChannel(ctx,nil);!errors.Is(err,context.DeadlineExceeded){t.Fatal("nil channel 必须响应取消")}
}
func TestServerChannelCancellation(t *testing.T) {
    ctx,cancel:=context.WithCancel(context.Background());cancel()
    if _,err:=SumChannel(ctx,make(chan int));!errors.Is(err,context.Canceled){t.Fatal("必须传播取消错误")}
}

package example
import ("context";"testing";"time")
func TestEvalChannelValues(t *testing.T) {
    values:=[]int{26,-14,0,17,-31,4};ch:=make(chan int,len(values));want:=0
    for _,x:=range values{ch<-x;want+=x};close(ch)
    got,err:=SumChannel(context.Background(),ch);if err!=nil||got!=want{t.Fatal(got,err,want)}
}
func TestEvalChannelPartialCancel(t *testing.T) {
    ctx,cancel:=context.WithCancel(context.Background());defer cancel()
    ch:=make(chan int);done:=make(chan struct{n int;err error},1)
    go func(){n,e:=SumChannel(ctx,ch);done<-struct{n int;err error}{n,e}}()
    ch<-17;ch<-(-4);cancel()
    select {case got:=<-done:if got.n!=13||got.err!=context.Canceled{t.Fatal(got)};case <-time.After(time.Second):t.Fatal("cancel ignored")}
}

